package org.example;

import dev.langchain4j.data.message.AiMessage;
import dev.langchain4j.data.message.ChatMessage;
import dev.langchain4j.data.message.SystemMessage;
import dev.langchain4j.data.message.UserMessage;
import dev.langchain4j.model.chat.request.ChatRequest;
import dev.langchain4j.model.chat.response.ChatResponse;
import dev.langchain4j.model.chat.response.StreamingChatResponseHandler;
import dev.langchain4j.model.ollama.OllamaChatModel;
import dev.langchain4j.model.ollama.OllamaStreamingChatModel;
import org.eclipse.paho.client.mqttv3.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.yaml.snakeyaml.Yaml;

import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.lang.reflect.Array;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

public class App {
    public static final String MQTT_OUTPUT_MARKER = "(SEND: ";
    public static final String MQTT_OUTPUT_END_MARKER = ")";
    public static final int MQTT_OUTPUT_MARKER_LENGTH = MQTT_OUTPUT_MARKER.length();
    private static final int MQTT_OUTPUT_END_MARKER_LENGTH = MQTT_OUTPUT_END_MARKER.length();
    private static Logger LOG = LoggerFactory.getLogger(App.class);
    private static MqttAsyncClient mqtt;
    private static Queue<String> inputs = new ArrayDeque<>();
    private static OllamaStreamingChatModel ollama;
    private static String output;

    public static void main(String[] args) {
        if (args.length != 1) {
            fatal("Usage: java -jar App.jar config.yaml");
        }

        String configPath = args[0];
        try {
            InputStream configStream = new FileInputStream(configPath);
            Map<String, Object> config = (new Yaml()).load(configStream);

            if (!config.containsKey("mqtt")) {
                fatal("Config file does not contain mqtt key");
            }

            setupMqtt((Map<String, Object>) config.get("mqtt"));

            if (!config.containsKey("ollama")) {
                fatal("Config file does not contain ollama key");
            }

            setupOllama((Map<String, Object>) config.get("ollama"));

            if (!config.containsKey("prompt")) {
                fatal("Config file does not contain prompt key");
            }

            final String prompt = (String) config.get("prompt");

            StringBuilder request = new StringBuilder("I exist.");
            List<ChatMessage> messages = new ArrayList<>();
            messages.add(SystemMessage.from(prompt));
            while (true) {
                System.out.println("----");
                CompletableFuture<ChatResponse> iteration = new CompletableFuture<>();
                if (!inputs.isEmpty()) {
                    synchronized (inputs) {
                        inputs.stream()
                                .peek(s -> System.out.println(String.format("Input: %s\n----", s)))
                                .map(s -> String.format("(Event: %s)", s))
                                .map(UserMessage::from)
                                .forEach(messages::add);
                        inputs.clear();
                    }
                }
                messages.add(SystemMessage.from(request.toString()));
                ollama.chat(ChatRequest.builder().messages(messages).build(), new StreamingChatResponseHandler() {
                    @Override
                    public void onPartialResponse(String s) {
                        System.out.print(s);
                    }

                    @Override
                    public void onCompleteResponse(ChatResponse chatResponse) {
                        System.out.println("");
                        iteration.complete(chatResponse);
                    }

                    @Override
                    public void onError(Throwable throwable) {
                        iteration.completeExceptionally(throwable);
                    }
                });
                try {
                    iteration.join();
                } catch (Exception e) {
                    LOG.warn("Iteration failed", e);
                    continue;
                }
                final String response = iteration.get().aiMessage().text();

                request.setLength(0);
                int outputMarker = -1;
                int outputEnd = 0;
                while ((outputMarker = response.indexOf(MQTT_OUTPUT_MARKER, outputEnd)) > -1) {
                    request.append(response.substring(outputEnd, outputMarker));
                    outputEnd = response.indexOf(MQTT_OUTPUT_END_MARKER, outputMarker);
                    if (outputEnd > outputMarker) {
                        try {
                            mqtt.publish(output, response.substring(outputMarker + MQTT_OUTPUT_MARKER_LENGTH, outputEnd).getBytes(), 2, false);
                        } catch (MqttException e) {
                            fatal("Error publishing message", e);
                        }
                        outputEnd += MQTT_OUTPUT_END_MARKER_LENGTH;
                    } else if (outputEnd == -1) {
                        outputEnd = response.length() - 1;
                    }
                }
                if (outputEnd == 0) {
                    request.append(response);
                } else {
                    request.append(response.substring(outputEnd));
                }

                if (request.isEmpty()) {
                    request.append("thoughts?");
                }

                if (messages.size() > 10) {
                    messages = messages.subList(messages.size() - 10, 10);
                    messages.add(0, SystemMessage.from(prompt));
                }
            }
        } catch (FileNotFoundException e) {
            fatal("Config file not found", e);
        } catch (ExecutionException e) {
            fatal("Error", e);
        } catch (InterruptedException e) {
            fatal("Error", e);
        }
    }

    private static void setupOllama(Map<String, Object> config) {
                if (!config.containsKey("server")) {
                    fatal("Config file does not contain ollama/server key");
                }



                Map<String, String> headers = new HashMap<>();
                if (config.containsKey("token")) {
                    headers.put("Authorization", "Bearer " + config.get("token"));
                }

                ollama = new OllamaStreamingChatModel.OllamaStreamingChatModelBuilder()
                        .baseUrl(config.get("server").toString())
                        .customHeaders(headers)
                        .temperature(0.5)
                        .logRequests(false)
                        .logResponses(false)
                        .modelName(config.get("model").toString())
                        .build();
    }

    private static void setupMqtt(Map<String, Object> config) {
        if (!config.containsKey("broker")) {
            fatal("Config file does not contain mqtt/broker key");
        } else if (!config.containsKey("id")) {
            fatal("Config file does not contain mqtt/id key");
        } else if (!config.containsKey("input")) {
            fatal("Config file does not contain mqtt/input key");
        } else if (!config.containsKey("output")) {
            fatal("Config file does not contain mqtt/output key");
        } else if (!config.containsKey("status")) {
            fatal("Config file does not contain mqtt/status key");
        }

        output = config.get("output").toString();

        try {
            mqtt = new MqttAsyncClient(
                    config.get("broker").toString(),
                    config.get("id").toString()
                );
        } catch (MqttException e) {
            fatal("Error creating mqtt", e);
        }


        MqttConnectOptions options = new MqttConnectOptions();
        options.setAutomaticReconnect(true);
        options.setWill(config.get("status").toString(), "disconnected".getBytes(), 2, true);

        try {
            mqtt.connect(options, new IMqttActionListener() {
                @Override
                public void onSuccess(IMqttToken iMqttToken) {
                    try {
                        iMqttToken.getClient().subscribe(config.get("input").toString(), 2, new IMqttMessageListener() {
                            @Override
                            public void messageArrived(String topic, MqttMessage message) throws Exception {
                                synchronized (inputs) {
                                    inputs.add(message.toString());
                                }
                            }
                        });
                    } catch (MqttException e) {
                        fatal("Error subscribing to input mqtt topic", e);
                    }
                }

                @Override
                public void onFailure(IMqttToken iMqttToken, Throwable throwable) {
                    fatal("Error connecting to MQTT broker", throwable);
                }
            });
        } catch (MqttException e) {
            fatal("Error connecting to MQTT broker", e);
        }
    }

    private static void fatal(String message, Object... args) {
        if (mqtt != null) {
            try {
                mqtt.close();
            } catch (MqttException e) {
                LOG.error("failed to disconnect MQTT", e);
            }
        }
        LOG.error(message, args);
        System.exit(1);
    }
}
